package org.xar.ck3.control.wave2.military.combatwire.phaseevent;

import static org.xar.ck3.control.wave2.military.combatwire.phaseevent.PhaseJson.*;
import static org.xar.ck3.control.wave2.military.combatwire.phaseevent.PhaseConstants.*;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;

/** Every direct stock transition handler writes only an isolated snapshot, never native/Game state. */
final class PhaseTransitions {
    private PhaseTransitions() { }
    static void execute(String key,ObjectNode args,PhaseTrialState s,PhaseDrawTape tape){switch(key){
        case "no_op" -> s.log.add(obj().put("transition",key).put("applied",false));
        case "observational_only" -> {ArrayNode effects=array(args.get("effects"),"observations");for(JsonNode e:effects){String effect=text(e,"effect");unique(s.observations,effect);if(Set.of("delayed_epilepsy_risk","delayed_infection_or_treatment","hold_court_delayed_event").contains(effect))unique(s.delayed,effect);}ObjectNode log=obj().put("transition",key).put("applied",true);log.set("effects",effects.deepCopy());s.log.add(log);}
        case "increase_wound_or_die" -> wound(s);
        case "maim_random" -> maim(s,tape);
        case "kill_character" -> {Long killer=null;String policy=text(args.get("killer"),"killer");if(policy.equals("root"))killer=s.rootId;else if(policy.equals("selected_enemy_knight_or_null"))killer=s.selected;else if(policy.equals("selected_enemy_knight_if_both_alive_else_null")&&s.selected!=null&&s.alive("root")&&s.alive("selected_enemy_knight"))killer=s.selected;kill(s,text(args.get("target"),"target"),text(args.get("reason"),"reason"),killer);}
        case "knight_increase_prowess_chance" -> prowess(s,tape,text(args.get("target"),"target"));
        case "berserker_kill_random_reason" -> randomKill(s,tape,true);
        case "shieldmaiden_kill_random_reason" -> randomKill(s,tape,false);
        case "add_trait" -> trait(s,text(args.get("target"),"target"),text(args.get("trait"),"trait"));
        case "require_character_stat_recompute" -> recompute(s,text(args.get("target"),"target"));
        case "require_participant_detach_recompute" -> detach(s,text(args.get("target"),"target"));
        case "set_variable" -> {String target=text(args.get("target"),"target"),name=text(args.get("name"),"variable");JsonNode value;if(target.equals("root.liege")){long raw=signed(args.get("value_raw"),"variable raw");s.liegeVariables.put(name,raw);s.refs.put("root.liege.accolade_progress_raw",raw);value=J.numberNode(raw);}else{require(target.equals("root"),"unknown variable target");boolean b=bool(args.get("value"),"variable value");s.rootVariables.put(name,b);value=J.booleanNode(b);}ObjectNode log=obj().put("transition","set_variable").put("target",target).put("name",name).put("applied",true);log.set("value",value);s.log.add(log);}
        default -> throw new IllegalArgumentException("transition has no executor: "+key);
        }}
    static void recompute(PhaseTrialState s,String target){long id=s.targetId(target);unique(s.characterRecompute,id);unique(s.strengthRecompute,target.equals("root")?s.side:s.enemy);s.invalidate(id,false);s.log.add(obj().put("transition","require_character_stat_recompute").put("target_character_id",id).put("timing","same_day_unverified").put("applied",true));}
    static void detach(PhaseTrialState s,String target){long id=s.targetId(target);boolean requested=PhaseTrialState.contains(s.detachRecompute,id);unique(s.detachRecompute,id);int side;if(target.equals("root")){PhaseTrialState.remove(s.combatMembership,id);side=s.side;if(s.commander!=null&&s.commander==id)s.commander=null;}else{PhaseTrialState.remove(s.enemyMembership,id);PhaseTrialState.remove(s.orderedEnemy,id);side=s.enemy;}unique(s.strengthRecompute,side);s.invalidate(id,true);ObjectNode log=obj().put("transition","require_participant_detach_recompute").put("target_character_id",id).put("side_index",side).put("timing","same_day_unverified").put("applied",!requested);if(requested)log.put("reason","already_detached");else log.putNull("reason");s.log.add(log);}
    static void kill(PhaseTrialState s,String target,String reason,Long killer){long id=s.targetId(target);boolean alive=s.alive(target);if(alive)s.setAlive(target,false);ObjectNode log=obj().put("transition","kill_character").put("target_character_id",id).put("reason",reason).put("applied",alive);if(killer==null)log.putNull("killer_character_id");else log.put("killer_character_id",killer);s.log.add(log);if(alive)detach(s,target);}
    static void trait(PhaseTrialState s,String target,String trait){long id=s.targetId(target);if(!s.alive(target)){s.log.add(obj().put("transition","add_trait").put("target_character_id",id).put("trait",trait).put("applied",false).put("reason","target_not_alive"));return;}require(target.equals("root"),"stock trait target must be root");String path="root.traits."+trait;boolean before=bool(s.refs.get(path),path);s.refs.put(path,true);if(trait.equals("incapable"))s.refs.put("root.is_incapable",true);s.recomputeRoot();s.log.add(obj().put("transition","add_trait").put("target_character_id",id).put("trait",trait).put("before",before).put("after",true).put("applied",!before));}
    static void wound(PhaseTrialState s){if(!s.alive("root")){s.log.add(obj().put("transition","increase_wound_or_die").put("target_character_id",s.rootId).put("applied",false).put("reason","target_not_alive"));return;}long rank=signed(s.refs.get("root.traits.wounded.rank_raw"),"wounded rank");if(rank>=300000){s.log.add(obj().put("transition","increase_wound_or_die").put("target_character_id",s.rootId).put("before_rank_raw",rank).put("after_rank_raw",rank).put("applied",true).put("outcome","death"));kill(s,"root","death_fight",s.selected);return;}long fragile=signed(s.refs.get("root.traits.fragile_bones.rank_raw"),"fragile rank"),xp=signed(s.refs.get("root.traits.fragile_bones.xp_raw"),"fragile xp");long delta=xp>=5000000?300000:fragile>0?200000:100000;long updated=BigInteger.valueOf(rank).add(BigInteger.valueOf(delta)).min(BigInteger.valueOf(300000)).longValueExact();s.refs.put("root.traits.wounded.rank_raw",updated);s.recomputeRoot();s.log.add(obj().put("transition","increase_wound_or_die").put("target_character_id",s.rootId).put("before_rank_raw",rank).put("rank_delta_raw",delta).put("after_rank_raw",updated).put("applied",true).put("outcome","wounded"));recompute(s,"root");}
    static void maim(PhaseTrialState s,PhaseDrawTape tape){if(!s.alive("root")){s.log.add(obj().put("transition","maim_random").put("applied",false).put("reason","root_not_alive"));return;}List<String> traits=List.of("one_legged","disfigured","one_eyed","maimed");List<Long> weights=new ArrayList<>(List.of(400000L,200000L,400000L,400000L));for(int i=0;i<4;i++)if(bool(s.refs.get("root.traits."+traits.get(i)),"maim trait"))weights.set(i,0L);int selected=tape.take("maim_random:source_order",weights);if(selected<0){ObjectNode log=obj().put("transition","maim_random").put("applied",false).put("reason","no_valid_branch");log.set("weights_source_order",tape.weights(weights));s.log.add(log);return;}String branch=MAIM.get(selected).textValue(),trait=traits.get(selected);s.refs.put("root.traits."+trait,true);s.recomputeRoot();ObjectNode log=obj().put("transition","maim_random").put("selected_branch",branch).put("target_character_id",s.rootId).put("trait",trait).put("applied",true);log.set("weights_source_order",tape.weights(weights));s.log.add(log);if(selected==3){s.delayed.add("recently_maimed_modifier_one_year");recompute(s,"root");}else wound(s);}
    static void validateBlade(ObjectNode row){keys(row,"education_martial education_martial_prowess lifestyle_blademaster lifestyle_blademaster_xp_raw shrewd physique_good intellect_good culture_blademaster_traits_more_common","blademaster");for(String key:List.of("education_martial","education_martial_prowess","intellect_good")){ArrayNode values=array(row.get(key),key);int count=key.equals("education_martial")?5:key.equals("education_martial_prowess")?4:3;require(values.size()==count,"malformed "+key);for(JsonNode v:values)bool(v,key);}for(String key:List.of("lifestyle_blademaster","shrewd","physique_good","culture_blademaster_traits_more_common"))bool(row.get(key),key);require(signed(row.get("lifestyle_blademaster_xp_raw"),"blade XP")>=0,"negative blade XP");}
    static void prowess(PhaseTrialState s,PhaseDrawTape tape,String target){long id=s.targetId(target),learning=s.learning(target);long noOp=checked(BigInteger.valueOf(6000000).subtract(BigInteger.valueOf(learning).multiply(BigInteger.TWO)),"prowess no-op");if(s.warfare(target))noOp=multiply(noOp,50000);ObjectNode blade=s.blade(target);validateBlade(blade);long weight=1000000;boolean education=false;for(JsonNode flag:blade.get("education_martial"))education|=flag.booleanValue();if(education)weight+=500000;int[] martial={4,8,12,16},intellect={5,15,30};for(int i=0;i<4;i++)if(blade.get("education_martial_prowess").get(i).booleanValue())weight+=martial[i]*100000L;for(String key:List.of("lifestyle_blademaster","shrewd","physique_good"))if(blade.get(key).booleanValue())weight+=key.equals("lifestyle_blademaster")?1500000:1000000;for(int i=0;i<3;i++)if(blade.get("intellect_good").get(i).booleanValue())weight+=intellect[i]*100000L;if(blade.get("culture_blademaster_traits_more_common").booleanValue())weight=multiply(weight,300000);if(blade.get("lifestyle_blademaster").booleanValue()&&signed(blade.get("lifestyle_blademaster_xp_raw"),"blade xp")>=10000000)weight=0;List<Long> weights=List.of(noOp,3000000L,weight);int selected=tape.take("knight_increase_prowess:source_order",weights);ObjectNode log=obj().put("transition","knight_increase_prowess_chance").put("target_character_id",id);log.set("weights_source_order",tape.weights(weights));if(selected<0){log.putNull("selected_branch").put("applied",false);s.log.add(log);return;}String branch=List.of("no_op","add_prowess","rank_blademaster").get(selected);if(selected==1)s.prowess(target,add(s.prowess(target),100000));else if(selected==2){boolean before=bool(blade.get("lifestyle_blademaster"),"blade");long xp=signed(blade.get("lifestyle_blademaster_xp_raw"),"blade XP");if(!before){blade.put("lifestyle_blademaster",true);if(target.equals("root"))s.refs.put("root.traits.lifestyle_blademaster",true);}else if(xp<10000000)blade.put("lifestyle_blademaster_xp_raw",Math.min(10000000,xp+1000000));}log.put("selected_branch",branch).put("applied",selected!=0);s.log.add(log);if(selected!=0)recompute(s,target);}
    static void randomKill(PhaseTrialState s,PhaseDrawTape tape,boolean berserker){String key=berserker?"berserker_kill_random_reason":"shieldmaiden_kill_random_reason";if(!s.alive("selected_enemy_knight")){s.log.add(obj().put("transition",key).put("applied",false).put("reason","target_not_alive"));return;}List<Long> weights=new ArrayList<>();for(int i=0;i<(berserker?9:5);i++)weights.add(1000000L);if(berserker){ObjectNode r=s.selectedRefs();boolean brave=bool(r.get("selected_enemy_knight.traits.brave"),"brave"),craven=bool(r.get("selected_enemy_knight.traits.craven"),"craven");weights.set(6,brave?0L:100000L+(craven?9900000L:0));}int branch=tape.take(berserker?"berserker_kill_reason:source_order":"shieldmaiden_kill_reason:source_order",weights);kill(s,"selected_enemy_knight",(berserker?"berserker_battle_reason_":"shieldmaiden_battle_reason_")+branch,s.rootId);}
}
